#!/usr/bin/env bash
# The town kit: five bundled Codex sheets in the approved style (style test B as the reference), three at a time.
set -euo pipefail
W=~/scratch/art/town; mkdir -p "$W"
REF=~/scratch/style-test/B/style-b.png
VIEW="Classic top-down RPG view as in Game Boy Advance games like The Minish Cap: the ground seen from above, buildings and objects facing the viewer squarely (front wall facing straight down the screen, roof seen from above-front, NOT at an angle, NOT isometric)."
PX="Game Boy Advance era pixel art in the same style as the reference image: crisp hard-edged square pixels, every pixel visible, a limited warm storybook palette (umber, rust, amber, cream, soft moss green), 1-pixel dark warm-brown outlines on objects, light from the top left, no anti-aliasing, no text, no letters, no numbers."
ISO="Each subject alone on a flat pure #00FF00 green background with plenty of green around it and nothing touching the image edges or another subject; no ground under the subjects except their own small grass fringe."
gen() { ~/.agents/bin/offload image --model codex --ref "$REF" --size "$2" -n 1 --out "$W/$1" --name "town-$1" "$3" > "$W/$1.log" 2>&1 || echo "FAILED $1"; }

gen houses 1536x1024 "A town kit sheet: three buildings in one row. (1) A small thatched cottage, the player's home: three tiles wide, a round wooden front door exactly in the middle of the front wall, a lit window on each side of the door, a stone chimney on the right of the roof, flower boxes. (2) A two-storey timber-framed village tavern: five tiles wide, a wide wooden double door exactly in the middle of the front wall, warm lit windows, a hanging sign board shaped like a tankard (no writing), a few barrels by the wall. (3) A small stone village temple: five tiles wide, an arched wooden double door CLOSED exactly in the middle of the front wall, a little bell gable on top with a bronze bell, round window, steps up to the door. $VIEW $PX $ISO" &
gen works 1536x1024 "A town kit sheet: three subjects in one row. (1) The burned old tavern: a ruin, the charred timber frame of a house with its roof fallen in, black beams, ash, broken stones, a soot-black chimney still standing, small weeds growing back, four tiles wide. (2) A village blacksmith's open-sided forge shed: a shingled roof on wooden posts, a stone forge with glowing orange coals, a leather bellows, tongs and hammers hanging on the back wall, four tiles wide and two deep. (3) A village market stall: a wooden counter with a striped rust-and-cream cloth awning, baskets of apples and loaves, jars and bundles on the counter, three tiles wide. $VIEW $PX $ISO" &
gen props 1536x1024 "A town kit sheet of twelve small objects in a grid of 4 columns and 3 rows: (1) a round stone well with a little shingled roof, a rope and a bucket; (2) a round leafy oak tree, its trunk at the bottom; (3) a round green bush; (4) a small patch of wildflowers (white, yellow and pink) in short grass; (5) a wooden signpost with three blank arrow boards pointing different ways; (6) an iron street lamp post with a warm glowing lantern on top, tall and thin; (7) a wooden park bench; (8) two wooden barrels side by side; (9) a stack of wooden crates; (10) a blacksmith's iron anvil on a wooden stump; (11) a small vegetable garden: three rows of cabbages and carrots in tilled brown soil with a low woven wattle fence and a tiny scarecrow; (12) two short wooden posts with a thick rope across them and a small lantern hanging from the rope. $VIEW $PX $ISO" &
wait
gen pond 1536x1024 "A town kit sheet with ONE subject: a village pond seen from above in classic top-down RPG view, wider than it is tall (about seven tiles wide and five tiles tall), calm blue-green water with a few lily pads and soft light ripples, a grassy bank with reeds and a few round stones all round its edge, and a narrow wooden plank dock that starts on the TOP (north) bank a little left of centre and runs straight DOWN into the water for three planks' length. $PX $ISO" &
gen ground 1536x1536 "A tile kit sheet of four seamless ground textures seen straight from above, in a grid of 2 columns and 2 rows, each texture filling its whole square cell edge to edge with no border and no gap: (1) short meadow grass with a few tiny flowers, calm and even; (2) a packed-dirt village lane with small pebbles, calm and even; (3) the rounded grey-brown cobblestones of a village square, calm and even; (4) a dense forest canopy seen from directly above: overlapping round dark-green treetops, no ground showing. Every texture evenly lit with no vignette and no spotlight so it repeats without seams. $PX" &
wait
ls "$W"/*/
echo DONE
